-- Sync all 57 Verified Wildwood-to-Cape-May Corridor Venues
drop policy if exists "Crew can insert/update venues" on public.venues;
create policy "Crew can insert/update venues" on public.venues for all using (true) with check (true);

on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  neighborhood = excluded.neighborhood,
  address = excluded.address,
  cross_street = excluded.cross_street,
  lat = excluded.lat,
  lng = excluded.lng,
  website_url = excluded.website_url,
  phone = excluded.phone,
  is_year_round = excluded.is_year_round;
